public static void execute(LevelAccessor world, double x, double y, double z, Entity entity, Entity sourceentity) {
    if (entity == null || sourceentity == null) {
        return;
    }
    sourceentity.setDeltaMovement(new Vec3(0.0, 1.4, 0.0));
    if (world instanceof Level) {
        Level _level = (Level)world;
        if (!_level.isClientSide()) {
            _level.playSound(null, BlockPos.containing((double)x, (double)y, (double)z), (SoundEvent)ForgeRegistries.SOUND_EVENTS.getValue(new ResourceLocation("entity.slime.squish")), SoundSource.NEUTRAL, 1.0f, 1.0f);
        } else {
            _level.playLocalSound(x, y, z, (SoundEvent)ForgeRegistries.SOUND_EVENTS.getValue(new ResourceLocation("entity.slime.squish")), SoundSource.NEUTRAL, 1.0f, 1.0f, false);
        }
    }
    if (entity instanceof SpringslimeEntity) {
        ((SpringslimeEntity)entity).setAnimation("2");
    }
    ThermalShockMod.queueServerWork(20, () -> {
        Level _level;
        if (!entity.level().isClientSide()) {
            entity.discard();
        }
        if (world instanceof Level) {
            _level = (Level)world;
            if (!_level.isClientSide()) {
                _level.playSound(null, BlockPos.containing((double)x, (double)y, (double)z), (SoundEvent)ForgeRegistries.SOUND_EVENTS.getValue(new ResourceLocation("entity.slime.death")), SoundSource.NEUTRAL, 1.0f, 1.0f);
            } else {
                _level.playLocalSound(x, y, z, (SoundEvent)ForgeRegistries.SOUND_EVENTS.getValue(new ResourceLocation("entity.slime.death")), SoundSource.NEUTRAL, 1.0f, 1.0f, false);
            }
        }
        if (world instanceof ServerLevel) {
            _level = (ServerLevel)world;
            _level.sendParticles((ParticleOptions)ParticleTypes.POOF, x, y, z, 15, 1.0, 1.0, 1.0, 0.3);
        }
    });
}

